package com.hotelmanagement.hms.purchase.model; import com.hotelmanagement.hms.shared.model.BranchEntity; import jakarta.persistence.*; import java.math.*; import java.util.*;
@Entity @Table(name="purchase_orders") public class PurchaseOrder extends BranchEntity { @Column(name="vendor_id",nullable=false) UUID vendorId; String reference; @Enumerated(EnumType.STRING) PurchaseOrderStatus status; BigDecimal total; @Column(name="actor_id") UUID actorId; protected PurchaseOrder(){} public static PurchaseOrder create(UUID h,UUID b,UUID v,String ref,BigDecimal total,UUID a){var p=new PurchaseOrder();p.hotelId=h;p.branchId=b;p.vendorId=v;p.reference=ref;p.total=total;p.actorId=a;p.status=PurchaseOrderStatus.DRAFT;return p;} public BigDecimal getTotal(){return total;} public String getReference(){return reference;} public UUID getVendorId(){return vendorId;} public PurchaseOrderStatus getStatus(){return status;} public void approve(){if(status!=PurchaseOrderStatus.DRAFT)throw new IllegalStateException("Only draft orders can be approved.");status=PurchaseOrderStatus.APPROVED;} public void receive(){if(status!=PurchaseOrderStatus.APPROVED)throw new IllegalStateException("Order must be approved first.");status=PurchaseOrderStatus.RECEIVED;} }

